import { useState } from 'react'
import { Container, CustomText } from '../../../../../components'
import { DownlineInfoStyle } from './index.style'
import { LANG_STRINGS } from '../../../../../lang'
import { useHistory } from 'react-router-dom'
import { DOWNLINE_INFO_TABS } from '../../constant'
import Tabs from '../../../../../components/Tabs'
import { useUpdateGlobal } from '../../../../../state/globalState/hooks/useGlobalContext'
import { AgentColorPallette } from '../../../../../configs/colorPallete'
import { NotFoundPageCard, NotFoundPageStyle } from '../../../../Public/NotFoundPage/index.style'
import { PAGE_NOT_FOUND } from '../../../../../images'

function DownlineInformation () {
  const history = useHistory()
  const [activeTab, setActiveTab] = useState(DOWNLINE_INFO_TABS[0])

  const [{ agentDetails }] = useUpdateGlobal()

  const handleTabClick = (tab) => {
    setActiveTab(tab)
  }

  const infoBox = (title, desc) => {
    return (
      <div className='info-box'>
        <CustomText
          color={AgentColorPallette.black}
          weight={700}
          size='14px'
          left='10px'
          bottom='10px'
        >
          {title}
        </CustomText>
        <CustomText
          color={AgentColorPallette.fontDarkerGrey}
          weight={500}
          size='13px'
          left='10px'
          lineHeight='1.5'
        >
          {desc}
        </CustomText>
      </div>

    )
  }

  const renderForDefault = () => {
    return(
      <NotFoundPageStyle>
          <NotFoundPageCard>
            <CustomText
              size='38px'
              weight={800}
              bottom='10px'
              color={AgentColorPallette.black}
            >
              {LANG_STRINGS.oops}
            </CustomText>
            <div>
              <img src={PAGE_NOT_FOUND} alt='' />
            </div>
            <CustomText
              size='16px'
              top='4px'
              weight={800}
              color={AgentColorPallette.black}
              textAlign='center'
            >
              {LANG_STRINGS.pageNotFound}
            </CustomText>
            <CustomText
              size='14px'
              top='6px'
              color={AgentColorPallette.fontGrey}
              textAlign='center'
            >
              {LANG_STRINGS.page404Description}
            </CustomText>
          </NotFoundPageCard>
        </NotFoundPageStyle>
    )
  }

  const renderBonusSection = () => {
    switch (agentDetails?.lv_details?.role) {
      case 'FOUNDER':
        return (
          <>
            {infoBox('Founder Bonus', 'Bonus yang diberikan kepada Founder atas keseluruhan transaksi/produksi polis, yang dikontribusikan oleh sejumlah tim pada level yang berada di bawah kelolaan Founder.')}
          </>
        )
      case 'LEADER':  
        return (
          <>
            {infoBox('Royalti Bonus', 'Bonus yang diberikan khusus kepada Mitra Bisnis, maksimal 10 kedalaman (hanya berhak diperoleh Mitra pada kategori level Mitra Bisnis).')}
            {infoBox('Overriding Bonus', 'Bonus yang diberikan kepada Mitra Bisnis dari keseluruhan produksi tim dan produksi pribadi (hanya berhak diperoleh Mitra pada kategori level Mitra Bisnis).')}
            {infoBox('Rekrutmen Bonus', 'Bonus yang diberikan untuk level Mitra Bisnis dan Mitra Eksekutif yang berhasil merekrut Mitra Eksekutif lain secara langsung (direct).')}
          </>
        )
      case 'PARTNER':
        return (
          <>
            {infoBox('Rekrutmen Bonus', 'Bonus yang diberikan untuk level Mitra Bisnis dan Mitra Eksekutif yang berhasil merekrut Mitra Eksekutif lain secara langsung (direct).')}
          </>
        )
      default:
        return (
          <>
            {renderForDefault()}
          </>
        )
    }
  }

  return (
    <Container
      title={LANG_STRINGS.information}
      showInnerHeader
      displayBackButton
      hideBottomTabs
      onBackClick={() => history.push('/downline')}
    >
      {(['FOUNDER', 'LEADER', 'PARTNER'].includes(agentDetails?.lv_details?.role)) ? 
     ( <DownlineInfoStyle>
        <Tabs
          data={DOWNLINE_INFO_TABS}
          defaultTab={activeTab}
          top='50px'
          borderBottom='#333333'
          onClick={handleTabClick}
          isSticky
        />
        {
          activeTab.value === 'bonus' && (
            <div className='tab-section'>
              <CustomText
                color={AgentColorPallette.black}
                weight={700}
                size='13px'
                left='10px'
              >
                Setiap kali <span className='blue-text'>Downline Saya</span> melakukan transaksi (sampai pembayaran selesai), saya berhak mendapatkan:
              </CustomText>
              {renderBonusSection()}
            </div>
          )
        }
        {
          activeTab.value === 'level' && (
            <div className='tab-section'>
              {infoBox('Mitra Bisnis', 'Jenjang satu level/tingkat di atas Mitra.')}
              {infoBox('Mitra Eksekutif', 'Mitra.')}
            </div>
          )
        }
      </DownlineInfoStyle>) : (renderBonusSection()) }
    </Container>
  )
}

export default DownlineInformation
